<?php
require_once 'includes/config.php'; require_admin();
$msg=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['toggle'])){ $id=(int)$_POST['id']; $status=(int)$_POST['status']?0:1; $q=$dbh->prepare('UPDATE teachers SET status=:s,updated_at=NOW() WHERE id=:id');$q->execute([':s'=>$status,':id'=>$id]);audit_log($dbh,'TEACHER_STATUS','Teacher '.$id.' status changed');$msg='Teacher status updated.'; }
$name=trim($_GET['name']??'');$class=(int)($_GET['class']??0);$gender=trim($_GET['gender']??'');
$profileTableExists=(bool)$dbh->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='srms_profile_photos'")->fetchColumn();
$profileSelect=$profileTableExists?"(SELECT stored_filename FROM srms_profile_photos p WHERE p.person_type='teacher' AND p.person_id=t.id LIMIT 1) AS profile_photo":"CAST(NULL AS CHAR) AS profile_photo";
$sql="SELECT t.*,$profileSelect,COALESCE(GROUP_CONCAT(DISTINCT CONCAT(c.ClassName,' - ',c.Section) ORDER BY c.ClassName SEPARATOR ', '),'Unassigned') assigned_classes,(SELECT COUNT(*) FROM teacher_student_assignments y WHERE y.teacher_id=t.id) student_count FROM teachers t LEFT JOIN teacher_class_assignments a ON a.teacher_id=t.id LEFT JOIN tblclasses c ON c.id=a.class_id WHERE 1=1";$p=[];
if($name!==''){$sql.=' AND t.full_name LIKE :name';$p[':name']="%$name%";}if($gender!==''){$sql.=' AND t.gender=:gender';$p[':gender']=$gender;}if($class){$sql.=' AND EXISTS(SELECT 1 FROM teacher_class_assignments af WHERE af.teacher_id=t.id AND af.class_id=:class)';$p[':class']=$class;}$sql.=' GROUP BY t.id ORDER BY t.full_name';$q=$dbh->prepare($sql);$q->execute($p);$rows=$q->fetchAll();$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassName,Section')->fetchAll();
function qstr($extra=[]){$base=$_GET;foreach($extra as $k=>$v)$base[$k]=$v;return http_build_query($base);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Teachers | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include('includes/topbar.php');?><div class="content-wrapper"><div class="content-container"><?php include('includes/leftbar.php');?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-md-8"><h2 class="title">Teacher Management</h2></div></div><div class="row"><div class="col-md-12"><div class="panel"><div class="panel-heading"><h5>Search, filter and export teachers</h5></div><div class="panel-body"><form method="get" class="row"><div class="col-md-3 form-group"><label>Search by name</label><input class="form-control" name="name" value="<?=e($name)?>" placeholder="Teacher name"></div><div class="col-md-3 form-group"><label>Assigned class</label><select class="form-control" name="class"><option value="0">All classes</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$class==$c['id']?'selected':''?>><?=e($c['ClassName'].' - '.$c['Section'])?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Gender</label><select class="form-control" name="gender"><option value="">All</option><option <?=$gender==='Male'?'selected':''?>>Male</option><option <?=$gender==='Female'?'selected':''?>>Female</option><option <?=$gender==='Other'?'selected':''?>>Other</option></select></div><div class="col-md-4 form-group"><label>&nbsp;</label><div><button class="btn btn-primary">Search / Filter</button> <a class="btn btn-default" href="manage-teachers.php">Reset</a> <a class="btn btn-success" href="add-teacher.php">+ Add Teacher</a></div></div></form><div class="m-t-10"><a class="btn btn-info btn-sm" href="export-teachers.php?<?=qstr(['format'=>'csv'])?>">Export CSV</a> <a class="btn btn-danger btn-sm" href="export-teachers.php?<?=qstr(['format'=>'pdf'])?>">Export PDF</a></div></div></div></div></div><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><div class="panel"><div class="panel-heading"><h5>Registered Teachers (<?=count($rows)?>)</h5></div><div class="panel-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>#</th><th>Photo</th><th>Teacher</th><th>Username</th><th>Email</th><th>Gender</th><th>Assigned Classes</th><th>Students</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php $i=1;foreach($rows as $r):?><tr><td><?=$i++?></td><td><?php if(!empty($r['profile_photo'])):?><img src="profile-photo.php?type=teacher&amp;id=<?=$r['id']?>" alt="Teacher photo" width="42" height="42" style="object-fit:cover;border-radius:50%"><?php else:?>—<?php endif;?></td><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['email'])?></td><td><?=e($r['gender']?:'—')?></td><td><?=e($r['assigned_classes'])?></td><td><?=$r['student_count']?></td><td><span class="label label-<?=$r['status']?'success':'default'?>"><?=$r['status']?'Active':'Inactive'?></span></td><td><a class="btn btn-primary btn-xs" href="edit-teacher.php?id=<?=$r['id']?>">Edit</a> <a class="btn btn-warning btn-xs" href="reset-teacher-password.php?id=<?=$r['id']?>">Reset Password</a><form method="post" class="inline-form" style="display:inline"><?php echo csrf_field();?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="<?=$r['status']?>"><button name="toggle" class="btn btn-default btn-xs"><?=$r['status']?'Disable':'Enable'?></button></form></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="10" class="text-center">No teachers match the selected filters.</td></tr><?php endif;?></tbody></table></div></div></div></div></div></div></div></div></body></html>
